/* ------------------------------------------------------------------ */
/*  HELPERS                                                            */
/* ------------------------------------------------------------------ */

function normalize(s) {
  return s
    .toLowerCase()
    .trim()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')      // strip accents: Sjögren -> sjogren
    .replace(/\(.*?\)/g, ' ')             // ignore parenthetical glosses
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\boe\b/g, 'e')
    .replace(/oe/g, 'e')                  // seborrhoeic -> seborrheic
    .replace(/ae/g, 'e')                  // haemangioma -> hemangioma
    .replace(/isation\b/g, 'ization')
    .replace(/\bthe\b|\bof\b|\ba\b/g, ' ')
    .replace(/s\b/g, '')                  // crude singular/plural fold
    .replace(/\s+/g, ' ')
    .trim();
}

function matchesDiagnosis(guess, puzzle) {
  const g = normalize(guess);
  if (!g) return false;
  const candidates = [puzzle.diagnosis, ...(puzzle.aliases || [])].map(normalize);
  return candidates.some((c) => c === g);
}

